export function BlockEditor({
  heading = "{{heading}}",
  body = "{{body}}",
  accent = "{{accent}}",
  showHandles = {{showHandles}},
  density = "{{density}}",
}) {
  const compact = density === "compact";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 15, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", border: "1.5px solid #24143022", borderRadius: 10, padding: 6, maxWidth: 420 }}>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 8, padding: compact ? "4px 10px" : 10, borderRadius: 6 }}>
        {showHandles && <span aria-hidden="true" style={{ color: "#24143055", paddingTop: 3, cursor: "grab" }}>&#10247;</span>}
        <h2 style={{ margin: 0, fontSize: compact ? 17 : 20, fontWeight: 700 }}>{heading}</h2>
      </div>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 8, padding: compact ? "4px 10px" : 10, borderRadius: 6 }}>
        {showHandles && <span aria-hidden="true" style={{ color: "#24143055", paddingTop: 3, cursor: "grab" }}>&#10247;</span>}
        <p style={{ margin: 0, color: "#241430cc" }}>{body}</p>
      </div>
      <button type="button" style={{ display: "inline-flex", alignItems: "center", gap: 6, margin: "6px 4px 4px",
        padding: "6px 10px", borderRadius: 6, border: `1.5px dashed ${accent}`, background: "transparent",
        color: accent, fontSize: 13, fontWeight: 500, cursor: "pointer" }}>
        <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M8 2v12M2 8h12" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" /></svg>
        Add block
      </button>
    </div>
  );
}
